def maxRemovals(source: str, pattern: str, targetIndices: List[int]) -> int:
    n = len(source)
    m = len(pattern)
    is_target = [False] * n
    for idx in targetIndices:
        is_target[idx] = True

    # curr_dp[i] is the minimum number of target indices used to form 
    # the prefix pattern[:j+1] ending at source index i.
    curr_dp = [float('inf')] * n
    for i in range(n):
        if source[i] == pattern[0]:
            curr_dp[i] = 1 if is_target[i] else 0

    for j in range(1, m):
        next_dp = [float('inf')] * n
        min_prev = float('inf')
        # To compute next_dp[i], we need min_{k < i} curr_dp[k]
        for i in range(n):
            if i > 0 and curr_dp[i-1] < min_prev:
                min_prev = curr_dp[i-1]

            if source[i] == pattern[j]:
                if min_prev != float('inf'):
                    next_dp[i] = min_prev + (1 if is_target[i] else 0)
        curr_dp = next_dp

    min_cost = min(curr_dp)
    return len(targetIndices) - min_cost
