        # new_dp[j] = max(dp[j] + stayScore[i][j],  max_{p != j}(dp[p] + travelScore[p][j]))

        # Optimization: To avoid O(n^2) per day, we just iterate. 
        # Given n=200, k=200, O(k*n^2) is 8 million, which fits in time.
        for curr in range(n):
            best_move = -1
            for prev in range(n):
                if prev == curr:
                    score = dp[prev] + stayScore[i][curr]
                else:
                    score = dp[prev] + travelScore[prev][curr]
                if score > best_move:
