def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    # A diagonal is defined by the property (row - col).
    # Bottom-left triangle including middle diagonal: row - col >= 0
    # Top-right triangle: row - col < 0

    # Dictionary to store elements of each diagonal
    diagonals = {}

    for r in range(n):
        for c in range(n):
            diff = r - c
            if diff not in diagonals:
                diagonals[diff] = []
            diagonals[diff].append(grid[r][c])

    # Sort the diagonals based on the rules
    for diff, values in diagonals.items():
        if diff >= 0:
            # Bottom-left triangle (including middle): non-increasing order
            values.sort(reverse=True)
        else:
            # Top-right triangle: non-decreasing order
            values.sort()

    # Reconstruct the grid
    # We need to track which index of each diagonal we are currently placing
    indices = {diff: 0 for diff in diagonals}
    for r in range(n):
        for c in range(n):
            diff = r - c
            grid[r][c] = diagonals[diff][indices[diff]]
            indices[diff] += 1

    return grid
