def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    if n == 0:
        return grid

    # The diagonals are identified by the constant value of (row - col).
    # Bottom-left triangle (including middle): row - col >= 0
    # Top-right triangle: row - col < 0

    # We need to collect all elements for each diagonal.
    diagonals = {}
    for r in range(n):
        for c in range(n):
            diff = r - c
            if diff not in diagonals:
                diagonals[diff] = []
            diagonals[diff].append(grid[r][c])

    # Sort the diagonals based on the rules.
    for diff, values in diagonals.items():
        if diff >= 0:
            # Bottom-left (including middle): non-increasing
            values.sort(reverse=True)
        else:
            # Top-right: non-decreasing
            values.sort()

    # Map the sorted values back to the grid.
    # We use a pointer/index for each diagonal to place them back in order.
    diag_indices = {diff: 0 for diff in diagonals}
    for r in range(n):
        for c in range(n):
            diff = r - c
            grid[r][c] = diagonals[diff][diag_indices[diff]]
            diag_indices[diff] += 1

    return grid
