def longestPalindromicSubsequence(s: str, k: int):
    n = len(s)
    # memo[i][j][rem_k] 表示從 s[i...j] 中，在剩餘操作次數為 rem_k 的情況下能獲得的最長回文子序列
    memo = {}

    def get_dist(c1, c2):
        diff = abs(ord(c1) - ord(c2))
        return min(diff, 26 - diff)

    def dp(i, j, rem_k):
        if i > j:
            return 0
        if i == j:
            return 1
        if (i, j, rem_k) in memo:
            return memo[(i, j, rem_k)]

        # 選項 1：不包含 s[i]
        res = dp(i + 1, j, rem_k)
        # 選項 2：不包含 s[j]
        res = max(res, dp(i, j - 1, rem_k))

        # 選項 3：包含 s[i] 和 s[j]，嘗試將它們變為相同字元
        cost = get_dist(s[i], s[j])
        if rem_k >= cost:
            res = max(res, 2 + dp(i + 1, j - 1, rem_k - cost))

        memo[(i, j, rem_k)] = res
        return res

    # 使用遞迴加快開發，但考慮到 n=200，為了避免超過遞迴深度，可改用迭代或增加 limit
    import sys
    sys.setrecursionlimit(100000)
    return dp(0, n - 1, k)
