def longestPalindromicSubsequence(s: str, k: int):
    n = len(s)
    dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for r in range(k + 1):
            dp[i][i][r] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            v1, v2 = ord(s[i]), ord(s[j])
            d = min(abs(v1 - v2), 26 - abs(v1 - v2))
            for r in range(k + 1):
                res0 = dp[i+1][j][r]
                res1 = dp[i][j-1][r]
                res = res0 if res0 > res1 else res1
                if r >= d:
                    prev = dp[i+1][j-1][r-d] if i + 1 <= j - 1 else 0
                    val = 2 + prev
                    if val > res:
                        res = val
                dp[i][j][r] = res
    return dp[0][n-1][k]
