from typing import List

def shiftDistance(s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
    total_cost = 0
    for char_s, char_t in zip(s, t):
        start = ord(char_s) - ord('a')
        end = ord(char_t) - ord('a')

        # Calculate cost to go forward (nextCost) and backward (previousCost)
        # To find min cost between two characters in a cyclic alphabet:
        # 1. Go directly forward: sum of nextCost from start to end
        # 2. Go directly backward: sum of previousCost from start down to end
        # However, the problem implies we can only move one step at a time with specific costs.
        # Since we want minimum cost and there's no "skip", this is a shortest path on a graph of 26 nodes.

        # Pre-calculate shortest paths for all pairs using Floyd-Warshall (since it's only 26 nodes)
        dist = [[float('inf')] * 26 for _ in range(26)]
        for i in range(26):
            dist[i][i] = 0
            # Move forward: i -> (i+1)%26
            dist[i][(i + 1) % 26] = min(dist[i][(i + 1) % 26], nextCost[i])
            # Move backward: i -> (i-1)%26
            dist[i][(i - 1) % 26] = min(dist[i][(i - 1) % 26], previousCost[i])

        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        total_cost += dist[start][end]

    return int(total_cost)

# Optimization: The above Floyd-Warshall is inside the loop. 
# Move it outside for O(26^3 + N).
def shiftDistance(s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
    dist = [[float('inf')] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0
        dist[i][(i + 1) % 26] = min(dist[i][(i + 1) % 26], nextCost[i])
        dist[i][(i - 1) % 26] = min(dist[i][(i - 1) % 26], previousCost[i])

    for k in range(26):
        for i in range(26):
            for j in range(26):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    for char_s, char_t in zip(s, t):
        total_cost += dist[ord(char_s) - ord('a')][ord(char_t) - ord('a')]
    return int(total_cost)
